def scope_saved_primitives(roots):
    """Use the bounded side-owner graph at every saved primitive call.

    The preparation/fill graphs, interfaces, source bindings and all subsequent
    checks stay intact. Call only for an explicitly opted-in candidate.
    """
    pending = list(roots); seen = set(); callers = []
    while pending:
        tree = pending.pop()
        if tree.as_pointer() in seen:
            continue
        seen.add(tree.as_pointer())
        for node in tree.nodes:
            if node.type != 'GROUP' or node.node_tree is None:
                continue
            child = node.node_tree
            if (child.get('st_separator_parity_policy') ==
                    'one_same_owner_quad_strip_to_unprotected_boundary_v1'):
                if child.get('st_separator_parity_scope') != 'all_faces_of_side_incident_carriageway_owners_v2':
                    callers.append(node)
            else:
                pending.append(child)
    if not callers:
        raise ValueError('No unscoped separator parity primitive reachable from these roots')
    shared = build(scoped_owners=True)
    for node in callers:
        node.node_tree = shared
    return len(callers)


def preparation():
    """Reconcile declared closed-hole parity before the existing fill assembly.

    Other declared openings are protected using indices recovered on the
    current mesh. The nested recovery is evaluated only for an odd boundary;
    accepted even boundaries pass through exactly. Source identities, rather
    than fixture names, choose every terminal, owner and repair strip.
    """
    from . import curved_separator_chain_boundary_nodes as chain
    name = 'Prochitecture Streets / Declared separator parity preparation v1'
    if name in bpy.data.node_groups:
        return bpy.data.node_groups[name]
    g = c.Graph(name)
    for key in ('Pavement','Mouths','Separators','Allowed Owners'):
        g.socket(key,'NodeSocketGeometry')
    for key in ('Geometry','Status'):
        g.socket(key,'NodeSocketGeometry','OUTPUT')
    inp = g.node('NodeGroupInput'); out = g.node('NodeGroupOutput')
    rows = inp.outputs['Separators']; count = c._count(g,rows)
    within = g.math('LESS_THAN',count,128.5)
    begin = g.node('GeometryNodeRepeatInput','Reconcile each declared opening on current pavement')
    end = g.node('GeometryNodeRepeatOutput','Retain local repair geometry and evidence')
    end.repeat_items.clear()
    for key in ('Geometry','Status'):
        end.repeat_items.new('GEOMETRY',key)
    begin.pair_with_output(end)
    g.bind(c.choose(g,within,count,0,'INT'),begin.inputs['Iterations'])
    g.bind(inp.outputs['Pavement'],begin.inputs['Geometry'])

    def boundary(at):
        node = g.node('GeometryNodeGroup','Recover declared opening on current pavement')
        node.node_tree = chain.build()
        g.bind(begin.outputs['Geometry'],node.inputs['Pavement'])
        g.bind(inp.outputs['Mouths'],node.inputs['Mouths'])
        for port,field in zip(chain.PORTS,('a_head','a_tail','b_head','b_tail')):
            g.bind(c._read(g,rows,'st_sb_'+field,at,'INT'),node.inputs[port])
        owner = c._read(g,rows,'st_sb_bundle_id',at,'INT')
        permission = c._select(g,inp.outputs['Allowed Owners'],
            g.math('COMPARE',c.named(g,'st_sr_bundle_id','INT'),owner))
        g.bind(permission,node.inputs['Allowed Owners'])
        return node

    current = boundary(begin.outputs['Iteration'])
    size = g.node('GeometryNodeAttributeDomainSize'); size.component = 'MESH'
    g.bind(current.outputs['Boundary'],size.inputs['Geometry'])
    needed = g.math('COMPARE',g.math('MODULO',size.outputs['Edge Count'],2.),1.)
    collect = g.node('GeometryNodeRepeatInput','Protect every other declared opening')
    collected = g.node('GeometryNodeRepeatOutput','Current protected boundary edge identities')
    collect.pair_with_output(collected)
    g.bind(c.choose(g,needed,count,0,'INT'),collect.inputs['Iterations'])
    protected = boundary(collect.outputs['Iteration'])
    join = g.node('GeometryNodeJoinGeometry')
    g.bind(collect.outputs['Geometry'],join.inputs['Geometry'])
    g.bind(protected.outputs['Boundary'],join.inputs['Geometry'])
    g.bind(join.outputs['Geometry'],collected.inputs['Geometry'])
    calls = []
    for side in ('Side B','Side A'):
        call = g.node('GeometryNodeGroup','Safe local parity cut from '+side)
        call.node_tree = build()
        for key,value in (('Geometry',begin.outputs['Geometry']),('Boundary',current.outputs['Boundary']),
                          ('Candidate Side',current.outputs[side]),('Protected Edges',collected.outputs['Geometry'])):
            g.bind(value,call.inputs[key])
        calls.append(call)
    first,second = calls
    result = c.choose(g,first.outputs['Valid'],first.outputs['Geometry'],second.outputs['Geometry'],'GEOMETRY')
    diagnostics = c.choose(g,first.outputs['Valid'],first.outputs['Diagnostics'],second.outputs['Diagnostics'],'GEOMETRY')
    result = c.choose(g,current.outputs['Valid'],result,begin.outputs['Geometry'],'GEOMETRY')
    diagnostics = c._store(g,diagnostics,'st_bundle_id',
        c._read(g,rows,'st_sb_bundle_id',begin.outputs['Iteration'],'INT'),'INT')
    status = g.node('GeometryNodeJoinGeometry')
    g.bind(begin.outputs['Status'],status.inputs['Geometry']); g.bind(diagnostics,status.inputs['Geometry'])
    g.bind(result,end.inputs['Geometry']); g.bind(status.outputs['Geometry'],end.inputs['Status'])
    g.bind(end.outputs['Geometry'],out.inputs['Geometry']); g.bind(end.outputs['Status'],out.inputs['Status'])
    g.g['st_separator_parity_policy'] = 'sequential_declared_holes_protect_all_other_openings_v1'
    return g.g


def candidate(original):
    """Opt in a saved chained assembly without changing its fill or guards."""
    from . import curved_separator_network_nodes as network
    if (not original.name.startswith(network.NAME) or 'Chained boundaries' not in original.name):
        raise ValueError('Require the declared closed chained-separator assembly')
    if original.get('st_separator_parity_preparation'):
        return original
    name = original.name+' / Local parity repair v1'
    if name in bpy.data.node_groups:
        existing = bpy.data.node_groups[name]
        if existing.get('st_separator_parity_preparation') != 1:
            raise ValueError('Conflicting parity candidate group: '+name)
        return existing
    tree = original.copy(); tree.name = name
    inp, = [n for n in tree.nodes if n.type=='GROUP_INPUT']
    consumers = [link.to_socket for link in inp.outputs['Pavement'].links]
    if not consumers:
        raise ValueError('Missing original pavement consumers')
    prepare = tree.nodes.new('GeometryNodeGroup'); prepare.label = 'Conforming separator parity before unchanged fill'
    prepare.node_tree = preparation()
    for key in ('Pavement','Mouths','Separators','Allowed Owners'):
        tree.links.new(inp.outputs[key],prepare.inputs[key])
    for socket in consumers:
        tree.links.new(prepare.outputs['Geometry'],socket)
    tree['st_separator_parity_preparation'] = 1
    return tree


def replace_references(roots):
    """Share one prepared assembly for every matching reachable library call."""
    from . import curved_separator_network_nodes as network
    pending = list(roots); seen = set(); callers = []
    while pending:
        tree = pending.pop()
        if tree.as_pointer() in seen:
            continue
        seen.add(tree.as_pointer())
        for node in tree.nodes:
            if node.type != 'GROUP' or not node.node_tree:
                continue
            child = node.node_tree
            if child.name.startswith(network.NAME) and 'Chained boundaries' in child.name:
                if not child.get('st_separator_parity_preparation'):
                    callers.append((node,child))
            else:
                pending.append(child)
    if not callers:
        raise ValueError('No unprepared chained separator assemblies reachable from roots')
    replacements = {tree:candidate(tree) for _,tree in callers}
    signature = lambda t: [(s.identifier,s.name,s.in_out,s.socket_type) for s in t.interface.items_tree
                           if s.item_type=='SOCKET']
    rows = []
    for old,new in replacements.items():
        if signature(old)!=signature(new):
            raise ValueError('Separator preparation changed the assembly interface')
        rows.append(dict(previous=old.name,candidate=new.name,
                         callers=sum(child==old for _,child in callers)))
    for node,old in callers:
        node.node_tree = replacements[old]
    return rows
